"""Demo: support bound and shearing membership (arity colimit)."""
from __future__ import annotations
from typing import Optional, Sequence

def support_bound(seq: Sequence[object], basepoint: object) -> Optional[int]:
    """Least N with seq[k] == basepoint for all k >= N (within the sample)."""
    last = -1
    for k, v in enumerate(seq):
        if v != basepoint:
            last = k
    return last + 1

def is_truncated_at(seq: Sequence[object], n: int, basepoint: object) -> bool:
    """Membership in the level-n truncated set {g : g[k]=basepoint for k>=n}."""
    return all(seq[k] == basepoint for k in range(n, len(seq)))

def main() -> None:
    seq = [3, 0, 5, 0, 0, 0, 0, 0]
    N = support_bound(seq, 0)
    print("sequence:", seq, "support bound N =", N)
    for n in range(9):
        print(f"  truncated-at-{n}: {is_truncated_at(seq, n, 0)}")
    print("First working level equals N =", N,
          "-- sheared vector = colimit of truncations.")

if __name__ == "__main__":
    main()

"""Demo: descent of a finitely-supported vector to a single subring stage."""
from __future__ import annotations
from dataclasses import dataclass
from typing import Sequence

@dataclass
class Poly:
    """Polynomial over K[x_0, x_1, ...] as (coeff, exponent-tuple) terms."""
    terms: tuple[tuple[int, tuple[int, ...]], ...]
    def max_var(self) -> int:
        m = -1
        for _, exps in self.terms:
            for i, e in enumerate(exps):
                if e > 0:
                    m = max(m, i)
        return m
    def in_stage(self, i: int) -> bool:
        """True iff the polynomial lies in S_i = K[x_0, ..., x_{i-1}]."""
        return self.max_var() < i

def variable(k: int) -> Poly:
    return Poly(((1, tuple(1 if j == k else 0 for j in range(k + 1))),))

def locate_stage(p: Poly) -> int:
    """Smallest i with p in S_i."""
    return p.max_var() + 1

def descend(seq: Sequence[Poly]) -> tuple[int, int]:
    """Return (M, N): common stage M and support level N."""
    N = 0
    for k, p in enumerate(seq):
        if p.terms and any(c != 0 for c, _ in p.terms):
            N = k + 1
    M = 0
    for k in range(N):
        M = max(M, locate_stage(seq[k]))
    return M, N

def main() -> None:
    zero = Poly(())
    seq = [variable(2), variable(0), variable(5), zero, zero]
    print("coordinate stages:", [locate_stage(p) for p in seq[:3]])
    M, N = descend(seq)
    print(f"merged stage M = {M}, support level N = {N}")
    print("all coords in S_M?", all(p.in_stage(M) for p in seq))

if __name__ == "__main__":
    main()

"""Demo: tropical (min-plus) shearing with basepoint +inf."""
from __future__ import annotations
from typing import Sequence

INF = float("inf")

def tropical_add(a: float, b: float) -> float:
    """min-plus addition a (+) b = min(a, b); additive identity is +inf."""
    return min(a, b)

def tropical_mul(a: float, b: float) -> float:
    """min-plus multiplication a (*) b = a + b; +inf absorbs."""
    return INF if a == INF or b == INF else a + b

def is_truncated_at(seq: Sequence[float], n: int) -> bool:
    """Membership in {g : g[k] = +inf for all k >= n}."""
    return all(seq[k] == INF for k in range(n, len(seq)))

def main() -> None:
    seq = [2.0, INF, 0.0, INF, INF, INF]
    print("tropical vector:", seq)
    print("min(3, inf) =", tropical_add(3.0, INF), " 3 (*) 4 =", tropical_mul(3.0, 4.0))
    for n in range(7):
        print(f"  truncated-at-{n}: {is_truncated_at(seq, n)}")
    print("Same colimit law as Witt, only the basepoint changed (0 -> +inf).")

if __name__ == "__main__":
    main()

