function DESCEND(seq, is_basepoint, locate_stage, join):
    N <- 0
    for k, x in enumerate(seq):
        if not is_basepoint(x):
            N <- k + 1            # support bound (arity)
    M <- bottom
    for k in 0 .. N-1:            # finitely many constraints
        M <- join(M, locate_stage(seq[k]))  # merge stages
    return (M, N)

function COMMON_UPPER_BOUND(indices, join, bottom):
    M <- bottom
    for i in indices:
        M <- join(M, i)          # binary directedness
    return M                     # M >= every i

function ESCAPING_COORDINATE(stage):
    # x_stage lies in S_{stage+1} but not in S_stage
    return stage                 # index of escaping coordinate
